INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('start', 0, 'The Beginning', 'Slow and safe. You learn the basics, pick up pebbles and finish with your Fountain.', 1, 'OAK_SAPLING', '');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('generator', 1, 'The First Real Generator', 'The Spring Stone and the stone generator: a ring around your Fountain. A wrong ring never costs you anything.', 1, 'STONE_BRICKS', 'q013');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('variety', 2, 'Different Generators', 'Dunes for sand and gravel, frost for ice and Frostium. The market opens.', 1, 'SAND', 'q021');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('tiers', 3, 'Raise the Generators', 'The Forge, the cores, tiers I to IV. This is where progress speeds up.', 1, 'AMETHYST_SHARD', 'q031');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('nether', 4, 'The Nether and the Ember', 'A portal, the Ember generator, quartz and soul sand.', 1, 'NETHERRACK', 'q060');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('end', 5, 'The End and the Void', 'The Void Lens opens /island end. The Voidwyrm guards the Void.', 1, 'END_STONE', 'q065');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('farm', 6, 'Farming and Food', 'A calm category. Play it alongside the generators.', 0, 'WHEAT', 'q013');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('forging', 7, 'Forge and Gear', 'Everything the Forge makes, from the bronze tools to the boss keys.', 0, 'BLAST_FURNACE', 'q057');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('machines', 8, 'Machines and Energy', 'Coal, cables on redstone, batteries, solar panels, then Miners that break the generator for you.', 0, 'REDSTONE', 'q021');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('market', 9, 'Market and Economy', 'Sell, buy and auction. The market never sells or buys ultra-rare items.', 0, 'EMERALD', 'q021');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('dungeons', 10, 'Dungeons', 'Rooms, secrets and boss keys. Floors 6 and 7 hold the Wing Cores.', 0, 'DEEPSLATE_BRICKS', 'q036');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('bosses', 11, 'The Bosses', 'Eight bosses of the world, each with its own silhouette and its glowing weak spot.', 0, 'DRAGON_HEAD', 'q212');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('mastery', 12, 'Mastery', 'Long goals for players who have done it all.', 0, 'NETHER_STAR', 'q065');
INSERT INTO quest_category (id, position, name, description, main, icon, unlock) VALUES ('challenges', 13, 'Challenges', 'Repeatable-feeling goals: bigger numbers, once each.', 0, 'TARGET', 'q021');
